import { AlertTriangle, Bell, BookOpen, CalendarDays, Camera, CheckCircle2, ChevronLeft, CircleDollarSign, Download, FileSpreadsheet, Home, LayoutGrid, Moon, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Sun, Users, WalletCards, X, BarChart3, CreditCard, MessageSquareText, MonitorCog, Upload, ExternalLink, Pencil, Trash2 } from "lucide-react";
